  b.hp--;
  if(b.hp<=0){b.alive=false;score+=10*wave;combo++;if(combo>1)score+=5*combo;particles.push(...createExplosion(b.x+b.w/2,b.y+b.h/2,b.color))}
  else{b.color='#555'}
  if(pierce<=0){break}
  pierce--;
}

